import { chromium, expect } from '@playwright/test';
import { readFile, writeFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
const dir = 'reference-captures/ordinary-playthrough-start/recreation';
const swf = '/home/ian/Projects/ianwijma/documented-bubble-tank-3/re/bt3/uncompressed.swf';
const digest = (bytes) => createHash('sha256').update(bytes).digest('hex');
const record = { started: new Date().toISOString(), sourceCommit: execFileSync('git', ['rev-parse', 'HEAD'], { encoding: 'utf8' }).trim(), buildId: (await readFile('.next/BUILD_ID', 'utf8')).trim(), SWFSha256: digest(await readFile(swf)), scope: 'Public original-size supplied-SWF recreation startup/movement/fire/pause only; no fixtures, seeded RNG, World access, upgrade adapter or state injection.', actions: [], captures: [], pageErrors: [], limitations: ['Ordinary inputs mirror the original session, but RNG/encounters and frame timing are not synchronized.', 'Source commit/build ID are metadata, not proof of every served bundle byte.', 'No full playthrough, audio comparison, pixel equality or complete-game parity result.'] };
const browser = await chromium.launch({ executablePath: '/usr/bin/google-chrome', headless: true, args: ['--no-sandbox', '--use-angle=swiftshader', '--enable-unsafe-swiftshader'] });
let page;
try {
 page = await browser.newPage({ viewport: { width: 1100, height: 1000 } });
 page.on('pageerror', (error) => record.pageErrors.push(error.message));
 const action = async (name, details, run) => { const started = new Date().toISOString(); await run(); record.actions.push({ name, ...details, started, ended: new Date().toISOString() }); };
 const stage = page.locator('.stage-frame');
 const capture = async (name) => { const path = "'`${dir}/${name}.png`; await stage.screenshot({ path }); record.captures.push({ name, path, sha256: digest(await readFile(path)) }); };
 await page.goto('"'http://127.0.0.1:3101/');
 await action('supply-original-SWF', {}, () => page.getByLabel('Bubble Tanks 3 Flash file').setInputFiles(swf));
 const menu = page.locator('.main-menu');
 await expect(menu).toHaveAttribute('data-menu-parked', 'false', { timeout: 60000 });
 await expect(menu).toHaveAttribute('data-title-frame', '179', { timeout: 60000 });
 await action('original-game-size', {}, () => page.getByRole('button', { name: 'Original game size', exact: true }).click());
 await capture('main-menu');
 await action('play', {}, () => page.getByRole('button', { name: 'Play', exact: true }).click());
 await capture('offline-tank-choice');
 await action('tank-choice-play', {}, () => page.getByRole('dialog', { name: 'Choose your tanks' }).getByRole('button', { name: 'PLAY', exact: true }).click());
 const canvas = page.locator('.game-canvas');
 await expect(canvas.locator('canvas')).toBeVisible();
 await expect.poll(async () => (await canvas.boundingBox())?.width).toBe(550);
 await action('focus-game', {}, () => canvas.focus());
 await page.waitForTimeout(300);
 await capture('tutorial-start');
 await action('leave-first-bubble', { key: 'd', holdMs: 12000 }, async () => { await page.keyboard.down('d'); try { await page.waitForTimeout(12000); } finally { await page.keyboard.up('d'); } });
 await capture('leave-first-bubble');
 const box = await canvas.boundingBox();
 const aim = { x: box.x + 125 * box.width / 550, y: box.y + 205 * box.height / 450 };
 await action('first-encounter-fire', { originalStagePoint: [125, 205], holdMs: 8000 }, async () => { await page.mouse.move(aim.x, aim.y); await page.mouse.down(); try { await page.waitForTimeout(8000); } finally { await page.mouse.up(); } });
 await capture('first-encounter-fire');
 await action('public-pause', { key: 'p' }, () => page.keyboard.press('p'));
 await expect(page.getByRole('dialog', { name: 'Paused', exact: true })).toBeVisible();
 await capture('public-pause');
 record.publicDescription = await page.locator('#map-description').textContent();
 record.completed = true;
} catch (error) {
 record.failure = String(error);
 throw error;
} finally {
 record.ended = new Date().toISOString();
 await browser.close();
 await writeFile("'`${dir}/manifest.json`, JSON.stringify(record, null, 2) + '"'\\n');
 console.log(JSON.stringify({ completed: record.completed ?? false, captures: record.captures.length, pageErrors: record.pageErrors, failure: record.failure }));
}
EOF
